#![forbid(unsafe_code)]
//! Import the CSS-owned CSSTree corpus inputs as raw `utf8-source` seeds.
//!
//! The corpus itself is owned by `surgeist-css` and generated by
//! `surgeist-generator`; this tool only reads the committed neutral
//! expectations and writes derived seed files plus `corpus-import.toml`, the
//! record of what was imported and what was excluded. Expectation files are
//! enumerated through the owner's generation report (`artifacts[].output_path`
//! and `case_count`), which lists every file including those in nested
//! directories; each file's actual case count must equal the report's, and the
//! total must equal the report's `counts.active`. Never hand-edit the output;
//! rerun it and inspect the diff.
//!
//! Usage: `import_csstree PACKAGE_DIRECTORY`
use serde_json::Value;
use std::{collections::BTreeMap, error::Error, fs, path::Path};

const CORPUS: &str = "../tests/corpus/csstree";
/// Contexts whose inputs are whole sheets, rules or declaration lists that the
/// `utf8-source` fronts parse as written.
const INCLUDED: [&str; 6] = [
    "stylesheet",
    "declarationList",
    "block",
    "rule",
    "declaration",
    "atrule",
];
/// Fragment contexts need a specific front (a property, selector or query
/// parser), so their inputs are not source seeds for the sheet and style
/// attribute fronts.
const EXCLUDED: [(&str, &str); 5] = [
    (
        "value",
        "a value needs its property, which the corpus does not carry",
    ),
    ("selector", "needs the selector fragment front"),
    ("selectorList", "needs the selector fragment front"),
    ("mediaQuery", "needs the media query fragment front"),
    ("atrulePrelude", "needs the at-rule prelude fragment front"),
];

type Case = (String, String);
type Corpus = (BTreeMap<String, Vec<Case>>, usize);

/// Every case of the corpus by context (the first directory under
/// `expectations/`), in the report's file order, with the report's total.
fn corpus_cases(corpus: &Path, report: &Value) -> Result<Corpus, Box<dyn Error>> {
    let mut by_context: BTreeMap<String, Vec<Case>> = BTreeMap::new();
    let mut total = 0_usize;
    for artifact in report["artifacts"].as_array().ok_or("artifacts array")? {
        let output = artifact["output_path"].as_str().ok_or("output path")?;
        let context = output
            .strip_prefix("expectations/")
            .and_then(|rest| rest.split('/').next())
            .ok_or("output path context")?;
        let document: Value = serde_json::from_slice(&fs::read(corpus.join(output))?)?;
        let cases = document["cases"].as_array().ok_or("cases array")?;
        let recorded = usize::try_from(artifact["case_count"].as_u64().ok_or("case count")?)?;
        if cases.len() != recorded {
            return Err(format!(
                "{output} holds {} cases, the report says {recorded}",
                cases.len()
            )
            .into());
        }
        total += cases.len();
        for case in cases {
            if case["status"] != "active" {
                return Err("inactive corpus case".into());
            }
            by_context.entry(context.to_owned()).or_default().push((
                case["id"].as_str().ok_or("case id")?.to_owned(),
                case["input"].as_str().ok_or("case input")?.to_owned(),
            ));
        }
    }
    if Some(total as u64) != report["counts"]["active"].as_u64() {
        return Err("cases do not add up to the report's active count".into());
    }
    Ok((by_context, total))
}

fn table(entries: Vec<(&str, toml::Value)>) -> toml::Value {
    toml::Value::Table(
        entries
            .into_iter()
            .map(|(key, value)| (key.to_owned(), value))
            .collect(),
    )
}

fn string(value: &str) -> toml::Value {
    toml::Value::String(value.to_owned())
}

fn integer(value: usize) -> Result<toml::Value, Box<dyn Error>> {
    Ok(toml::Value::Integer(i64::try_from(value)?))
}

fn main() -> Result<(), Box<dyn Error>> {
    let mut args = std::env::args_os().skip(1);
    let package = args
        .next()
        .ok_or("usage: import_csstree PACKAGE_DIRECTORY")?;
    if args.next().is_some() {
        return Err("usage: import_csstree PACKAGE_DIRECTORY".into());
    }
    let package = Path::new(&package);
    let corpus = package.join(CORPUS);
    let report: Value = serde_json::from_slice(&fs::read(
        corpus.join("expectations/generation-reports/all.json"),
    )?)?;
    let (by_context, total) = corpus_cases(&corpus, &report)?;
    let seeds = package.join("seeds/csstree");
    if seeds.exists() {
        fs::remove_dir_all(&seeds)?;
    }
    fs::create_dir_all(&seeds)?;

    let mut seen = std::collections::BTreeSet::new();
    let mut imported = Vec::new();
    let mut duplicates = 0_usize;
    for context in INCLUDED {
        for (index, (id, input)) in by_context
            .get(context)
            .ok_or("included context missing from the corpus")?
            .iter()
            .enumerate()
        {
            if !seen.insert(input.clone()) {
                duplicates += 1;
                continue;
            }
            let file = format!("{context}-{index:03}.case");
            fs::write(seeds.join(&file), input.as_bytes())?;
            imported.push(table(vec![
                ("file", string(&file)),
                ("corpus_id", string(id)),
            ]));
        }
    }
    let mut excluded = Vec::new();
    let mut excluded_total = 0_usize;
    for (context, reason) in EXCLUDED {
        let count = by_context
            .get(context)
            .ok_or("excluded context missing from the corpus")?
            .len();
        excluded_total += count;
        excluded.push(table(vec![
            ("context", string(context)),
            ("cases", integer(count)?),
            ("reason", string(reason)),
        ]));
    }
    if imported.len() + duplicates + excluded_total != total {
        return Err("imported, duplicate and excluded cases do not add up to the corpus".into());
    }

    let record = table(vec![
        ("schema", toml::Value::Integer(1)),
        ("owner", string("surgeist-css")),
        ("corpus", string("crates/surgeist-css/tests/corpus/csstree")),
        (
            "license",
            string("crates/surgeist-css/tests/corpus/csstree/LICENSE"),
        ),
        (
            "source_revision",
            string(
                report["source_revision"]
                    .as_str()
                    .ok_or("source revision")?,
            ),
        ),
        (
            "manifest_digest",
            string(
                report["manifest_digest"]
                    .as_str()
                    .ok_or("manifest digest")?,
            ),
        ),
        ("corpus_cases", integer(total)?),
        ("seed_directory", string("seeds/csstree")),
        ("target", string("surgeist-css::utf8-source")),
        ("duplicate_inputs", integer(duplicates)?),
        ("seed", toml::Value::Array(imported)),
        ("excluded", toml::Value::Array(excluded)),
    ]);
    let toml::Value::Table(record) = record else {
        return Err("record table".into());
    };
    fs::write(
        package.join("corpus-import.toml"),
        toml::to_string_pretty(&record)?,
    )?;
    Ok(())
}
